INSERT INTO `categories` VALUES (1,'የአንድምታ መጽሐፍት ክፍል','የብሉያት፣ ሐዲሳትና ሊቃውንት አንድምታ ትርጓሜያት','bi-journal-text','2026-10-05 20:27:35'),(2,'የገድላትና ድርሳናት መጽሐፍት ክፍል','የቅዱሳን ገድላት፣ ድርሳናትና ተአምራት','bi-shield-check','2026-10-05 20:27:35'),(3,'የመሰረተ ሃይማኖት ክፍል','ዶግማ፣ ቀኖና እና የመሰረተ ሃይማኖት ትምህርቶች','bi-mortarboard','2026-10-05 20:27:35'),(4,'የትምህርት እና ምክር አዘል ክፍል','መንፈሳዊ ምክር፣ ተግሳጽ እና ሕይወታዊ ትምህርቶች','bi-lightbulb','2026-10-05 20:27:35'),(5,'የታሪክ መጽሐፍት ክፍል','የቤተክርስቲያን፣ ገዳማትና ቅዱሳን ታሪክ','bi-hourglass-split','2026-10-05 20:27:35'),(6,'የክርስቲያናዊ ሥነምግባር መጻሕፍት ክፍል','ክርስቲያናዊ ምግባር፣ ጾም፣ ጸሎትና ንስሐ','bi-heart','2026-10-05 20:27:35'),(7,'የኮርስ መስጫ መጻሕፍት ክፍል','የሰንበት ትምህርት ቤት ኮርሶችና ማስተማሪያዎች','bi-journal-bookmark','2026-10-05 20:27:35'),(8,'የሥርዓተ ቤተክርስቲያን መጻሕፍት ክፍል','ፍትሐ ነገሥት፣ ቃለ አዋዲና የቤተክርስቲያን ሥርዓት','bi-bank','2026-10-05 20:27:35'),(9,'የአቡነ ሺኖዳ መጻሕፍት ክፍል','በብፁዕ ወቅዱስ አቡነ ሺኖዳ የተዘጋጁ ድርሰቶችና ትርጉሞች','bi-person-check','2026-10-05 20:27:35'),(10,'የጸሎትና የዜማ መጻሕፍት ክፍል','ቅዳሴ፣ ጸዋትወ ዜማ፣ ድጓና የጸሎት መጻሕፍት','bi-music-note-beamed','2026-10-05 20:27:35'),(11,'የመጽሐፍ ቅዱስ መጻሕፍት ክፍል','ብሉይና ሐዲስ ኪዳን መጻሕፍት ቅዱሳት','bi-book','2026-10-05 20:27:35'),(12,'የሥርጉተ ሥላሴ መጽሐፍት ክፍል','የሥርጉተ ሥላሴ ልዩ የመጽሐፍት ስብስብ','bi-collection','2026-10-05 20:27:35');
